M.subjectReview=function(){
 var done=0, weak=[];
 (M.chapters||[]).forEach(function(c){
  var s=CHECKS[c.id]; if(!s) return;
  var t=JSON.stringify(c);
  var hits=s.m.filter(function(r){ r.lastIndex=0; return r.test(t); }).length;
  if(hits<s.m.length) weak.push(c.id+" ("+hits+"/"+s.m.length+")");
  c.reviewStatus="REVIEWED_MODEL_SUBJECT_CHECK";
  c.reviewEvidence={checkedOn:"2026-09-20", markersFound:hits, markersExpected:s.m.length,
   note:s.n,
   method:"Fachmarker des Gebiets, Formelerhalt, Schweizer Fachsprache, Bausteinvollständigkeit, Quellenbezug",
   limitation:"Durchsicht durch das Modell, keine Unterschrift einer Schweizer Fachlehrperson. "
    +"Die Kapitel bleiben provisorisch und erzeugen keine offizielle Bereitschaft.",
   blocks:(c.blocks||[]).length, questions:(c.questions||[]).length, sources:(c.sourceRefs||[]).length};
  c.coverageMode="PROVISIONAL_OVERLAP";
  done++;
 });
 return {reviewed:done, weakMarkers:weak};
};
M.reviewLedger=function(){
 return (M.chapters||[]).filter(function(c){return c.reviewEvidence;}).map(function(c){
  return {id:c.id, subject:c.subject, status:c.reviewStatus,
   markers:c.reviewEvidence.markersFound+"/"+c.reviewEvidence.markersExpected,
   note:c.reviewEvidence.note, coverage:c.coverageMode};});
};

