var RKEY="mnemika-residual-v1";
M.residualData=function(){ try{return JSON.parse(localStorage.getItem(RKEY)||"{}");}catch(e){return {};} };
M.setResidual=function(id,d){ var a=M.residualData(); a[id]=d;
 try{localStorage.setItem(RKEY,JSON.stringify(a));}catch(e){} return a; };
M.residualStatus=function(id){
 var s=M.RESIDUAL.filter(function(r){return r.id===id;})[0]; if(!s) return null;
 var d=(M.residualData()||{})[id]||{};
 var f=s.fields.filter(function(x){return String(d[x.k]||"").trim();}).length;
 return {id:id,title:s.title,filled:f,total:s.fields.length,complete:f===s.fields.length};
};
M.residualSummary=function(){
 var r=M.RESIDUAL.map(function(x){return M.residualStatus(x.id);});
 return {items:r, complete:r.filter(function(x){return x.complete;}).length, total:r.length};
};
M.residualAffectsReadiness=function(){ return false; };
M.renderResidual=function(id){
 var s=M.RESIDUAL.filter(function(r){return r.id===id;})[0]; if(!s) return "";
 var d=(M.residualData()||{})[id]||{};
 return '<form class="rs" data-rs="'+E(id)+'"><h3>'+E(s.title)+'</h3>'
  +'<p class="rs-why">'+E(s.why)+'</p>'
  +s.fields.map(function(f){ var v=d[f.k]||"";
    if(f.t==="select") return '<label class="rs-f"><span>'+E(f.l)+'</span>'
     +'<select name="'+E(f.k)+'"><option value="">noch offen</option>'
     +f.o.map(function(x){return '<option'+(x===v?" selected":"")+'>'+E(x)+'</option>';}).join("")
     +'</select></label>';
    return '<label class="rs-f"><span>'+E(f.l)+'</span><input name="'+E(f.k)+'" value="'+E(v)
     +'" placeholder="'+E(f.ph||"")+'"></label>';}).join("")
  +'<p class="rs-note">Diese Angaben verbessern deinen Lernplan. Eine ausgewiesene '
  +'Prüfungsbereitschaft entsteht daraus nicht.</p>'
  +'<div class="rs-act"><button type="submit">Übernehmen</button>'
  +'<button type="button" class="rs-clear">Leeren</button></div></form>';
};
M.wireResidual=function(host){
 if(!host) return;
 host.querySelectorAll("form.rs").forEach(function(f){
  f.onsubmit=function(ev){ ev.preventDefault();
   var d={}; f.querySelectorAll("[name]").forEach(function(x){ d[x.name]=x.value; });
   M.setResidual(f.dataset.rs,d);
   var s=M.residualStatus(f.dataset.rs);
   var n=f.querySelector(".rs-done")||document.createElement("p");
   n.className="rs-done"; n.textContent=s.filled+" von "+s.total+" Angaben gespeichert.";
   f.appendChild(n); };
  var c=f.querySelector(".rs-clear");
  if(c) c.onclick=function(){ M.setResidual(f.dataset.rs,{});
   f.querySelectorAll("[name]").forEach(function(x){x.value="";}); };
 });
};

