(function(){"use strict";var M=window.MNEMIKA;if(!M)return;
/* Die Selbstkorrekturen (Vorlagensätze, Hinweise, Quellen, Ablenker und
   Antwortlängen) liefen in Schleifen, die nach 100 Versuchen aufgaben.
   Startete die App langsam oder wurde der Bestand später neu aufgebaut,
   blieben sie unangewandt: auf einem langsamen Telefon hätten Lernende
   den unkorrigierten Stand gesehen, und die Prüfung schlug zufällig fehl.
   Dieser Wächter prüft mit den vorhandenen Audits und wendet nur an, was
   fehlt. Je Datenbestand höchstens fünf Anwendungen pro Korrektur, damit
   eine nicht konvergierende Korrektur nie in einer Schleife läuft. */
var tries=new WeakMap(), started=Date.now();
function allow(name){
 var key=M.chapters&&M.chapters[0]; if(!key||typeof key!=="object") return false;
 var t=tries.get(key); if(!t){ t={}; tries.set(key,t); }
 t[name]=(t[name]||0)+1; return t[name]<=5;
}
function noch(name){ var key=M.chapters&&M.chapters[0]; if(!key||typeof key!=="object") return false; var t=tries.get(key); return !t||(t[name]||0)<5; } /* R74: Audit ueberspringen, wenn allow() ohnehin nein sagen muss */
function check(){
 if(!M.chapters||!M.chapters.length) return;
 try{
  var ta=noch("templates")&&M.templateAudit&&M.templateAudit();
  if(ta&&ta.remaining>0&&M.rephraseTemplates&&allow("templates")) M.rephraseTemplates();
  var hc=noch("hints")&&M.hintCoverage&&M.hintCoverage();
  if(hc&&hc.share<95&&M.addHints&&allow("hints")) M.addHints();
  var pa=noch("provenance")&&M.provenanceAudit&&M.provenanceAudit();
  if(pa&&pa.share<99&&M.applyProvenance&&allow("provenance")) M.applyProvenance();
  var da=noch("distractors")&&M.distractorAudit&&M.distractorAudit();
  if(da&&(da.repeatedMax>30||da.longestShare>34||da.longRepeatMax>9)&&M.ensureDistractors&&allow("distractors")) M.ensureDistractors(true);
 }catch(e){ console.warn("Selbstkorrektur:", e); }
}
function loop(){ if(!document.hidden) check(); setTimeout(loop, Date.now()-started<60000? 600 : 4000); }
loop();
})();

