function blockOf(c,q){ var r=null; (c.blocks||[]).forEach(function(b){ if(b&&b.check&&b.check.id===q.id) r=b; }); return r; }
function words(s){ return String(s||"").toLowerCase().replace(/[^a-zäöüéèàç0-9 ]+/g," ").split(/\s+/).filter(function(w){return w.length>4;}); }
