 (c.blocks||[]).forEach(function(bl){ var t=words((bl.label||"")+" "+(bl.body||[]).join(" ")); var s=0; qw.forEach(function(w){ if(t.indexOf(w)>=0) s++; }); if(s>sc){ sc=s; best=bl; } });
