 (c.blocks||[]).forEach(function(b){ if(b&&b.check) pool.push(b.check); });
 (c.questions||[]).forEach(function(x){ pool.push(x); });
 pool=pool.filter(function(x){ return x&&x.id!==q.id&&x.type!=="keywords"; });
