 if(!ready()){ try{ sessionStorage.setItem(KEY, "#"+p.join("/")); }catch(e){} return true; }
 if(r==="uebung"&&p[1]){ var c=M.chapter&&M.chapter(p[1]); M.quickStart({chapter:p[1],count:Math.min(30,Math.max(1,parseInt(p[2],10)||5)),title:(c&&c.title)||"Übung"}); }
 else if(r==="schnellstart"){ M.quickStart({count:Math.min(30,Math.max(1,parseInt(p[1],10)||10))}); }
 else if(r==="hilfe"){ if(M.showHelp) M.showHelp(p[1]||""); }
 else if(r==="pruefung"&&p[1]){ var s=(M.SUBJECTS&&M.SUBJECTS[p[1]]&&M.SUBJECTS[p[1]].label)||p[1]; M.quickStart({count:15,subject:p[1],mix:"weak",exam:true,title:"Prüfungsvorbereitung "+s}); }
