 bank.innerHTML=words.map(function(w,k){ return '<button type="button" data-w="'+k+'">'+E(w)+'</button>'; }).join("");
 var lab=document.createElement("p"); lab.className="wb-lab"; lab.textContent="Tippe ein Wort an, um die nächste Lücke zu füllen.";
 var tpl=host.querySelector(".template"); var at=tpl||inputs[inputs.length-1];
 at.parentNode.insertBefore(lab, at.nextSibling); lab.parentNode.insertBefore(bank, lab.nextSibling);
 var used={}; // Eingabe -> Knopf
 bank.querySelectorAll("[data-w]").forEach(function(b){ b.onclick=function(){
  var target=inputs.filter(function(x){return !x.disabled&&!x.value;})[0]; if(!target) return;
  target.value=words[+b.dataset.w]; b.disabled=true; used[inputs.indexOf(target)]=b; }; });
