  var ch=[].filter.call(v.querySelectorAll("button"),function(b){ return norm(b.textContent).indexOf(norm(c.title))>=0&&!b.hasAttribute("data-ct"); })[0];
  if(ch){ ch.click(); setTimeout(function(){ var go=[].filter.call(document.querySelectorAll("#v-chaptertest button"),function(b){return /Test starten|Starten|Beginnen/.test(b.textContent)&&b.offsetParent!==null;})[0]; if(go) go.click(); },250); return; }
  var sub=v.querySelector('[data-ct="'+c.subject+'"]'); if(sub&&!v.__ctSub){ v.__ctSub=1; sub.click(); }
  if(tries++<20) setTimeout(step,200);
