 if(hits.length>1) hits=hits.filter(function(e){ var sec=norm(e.q.statement||e.q.template||((e.q.options||[])[0])||((e.q.items||[])[0])||"").replace(/___/g,""); return sec&&txt.indexOf(sec.slice(0,30))>=0; });
