(function(){"use strict";var M=window.MNEMIKA;if(!M)return;
/* Iteration 14: doppelte Einstiege entfernen («Gegenprobe. Gegenprobe an …»). Beginnt der Text
   hinter einem fetten Einstieg mit demselben Wort, entfällt der Einstieg; der Satz bleibt vollständig. */
function norm(s){ return String(s||"").replace(/[.:]\s*$/,"").trim().toLowerCase(); }
function fix(root){ [].forEach.call(root.querySelectorAll("p"),function(p){ var f=p.firstElementChild; if(!f||!/^(STRONG|B)$/.test(f.tagName)||p.__dupFix) return;
 if(p.firstChild!==f&&!(p.firstChild.nodeType===3&&!p.firstChild.textContent.trim())) return;
 var lab=norm(f.textContent); if(lab.length<4) return; var rest=""; for(var n=f.nextSibling;n;n=n.nextSibling) rest+=n.textContent;
 rest=rest.trim(); if(rest.toLowerCase().indexOf(lab)===0){ p.__dupFix=true; var nx=f.nextSibling; f.remove(); if(nx&&nx.nodeType===3) nx.textContent=nx.textContent.replace(/^\s+/,""); } }); }
M.onDomChange(function(){ var v=document.getElementById("v-read"); if(v&&!v.hidden) fix(v); });
M.fixDuplicateLeadIns=fix;
})();

