(function(){"use strict";var M=window.MNEMIKA;if(!M)return;
/* Iteration 15: Abschluss als Merkmal am Body (für Farben und Hintergrund), Farbfeld einsetzen */
function prog(){ try{ return (M.activeProgram&&M.activeProgram())||""; }catch(e){ return ""; } }
function tick(){ var p=prog(); if(document.body.getAttribute("data-mn-prog")!==p) document.body.setAttribute("data-mn-prog",p);
 var bg=document.getElementById("mn-bg"); if(bg&&!document.getElementById("mn-aurora")){ var a=document.createElement("div"); a.id="mn-aurora"; a.setAttribute("aria-hidden","true"); bg.insertBefore(a,bg.firstChild); } }
tick(); M.everyTick(tick);
})();

