(function(){"use strict";var M=window.MNEMIKA;if(!M)return;
/* Iteration 16: «Englisch» zeigt nur Englisch. Auf der Fachseite einer Sprache bleiben nur die
   Wortschatzkarten dieser Sprache sichtbar. */
var SUBJ={english:"Englisch",french:"Französisch",italian:"Italienisch",spanish:"Spanisch",romansh:"Rätoromanisch",latin:"Latein"};
var ALL=Object.keys(SUBJ).map(function(k){return SUBJ[k];});
function current(){ var m=String(location.hash||"").match(/#learn\/([a-z-]+)/); if(m) return m[1]; var l=M.__v47Last||{}; return (l.view==="learn"&&typeof l.arg==="string")? l.arg : null; }
function run(){ var v=document.getElementById("v-learn"); if(!v||v.hidden) return; var sub=current(); var own=SUBJ[sub]; if(!own) return;
 [].forEach.call(v.querySelectorAll("*"),function(e){ if(e.children.length>1) return; var t=e.textContent.replace(/\s+/g," ").trim(); var m=t.match(/^Wortschatz (\S+)$/i); if(!m) return;
  var lang=ALL.filter(function(n){return n.toLowerCase()===m[1].toLowerCase();})[0]; if(!lang||lang===own) return;
  var card=e; for(var k=0;k<6&&card.parentElement&&card.parentElement!==v;k++){ if(card.querySelector&&card.querySelector("button")&&card.getBoundingClientRect().height>40) break; card=card.parentElement; }
  if(card&&card!==v&&!card.__langHidden){ card.__langHidden=true; card.style.display="none"; card.setAttribute("data-hidden-other-language",lang); } }); }
M.onDomChange(function(){ run(); }); window.addEventListener("hashchange",function(){ setTimeout(run,50); }); run();
M.hideOtherLanguages=run;
})();

