(function(){"use strict";var M=window.MNEMIKA;if(!M||!M.chapters)return;
/* Iteration 16: Wiederholungen aufräumen. Ein allgemeiner Methodensatz, der in drei oder mehr
   Lerneinheiten desselben Kapitels wörtlich wiederkehrt, bleibt nur in der ersten Einheit stehen. */
function plain(s){ return String(s||"").replace(/<[^>]+>/g," ").replace(/\s+/g," ").trim(); }
var removed=0;
function dedupe(c){ var count={}, blocks=(c.blocks||[]).filter(function(b){return b&&Array.isArray(b.body);});
 blocks.forEach(function(b){ var seen={}; plain(b.body.join(" ")).split(/(?<=[.!?])\s+/).forEach(function(s){ if(s.length>=35&&!seen[s]){ seen[s]=1; count[s]=(count[s]||0)+1; } }); });
 var rep=Object.keys(count).filter(function(s){return count[s]>=3;}); if(!rep.length) return;
 blocks.forEach(function(b,bi){ if(bi===0) return; b.body=b.body.map(function(x){ if(typeof x!=="string") return x; var y=x; rep.forEach(function(s){ var esc=s.replace(/[.*+?^${}()|[\]\\]/g,"\\$&"); var re=new RegExp("\\s*"+esc,"g"); if(re.test(y)){ y=y.replace(re,""); removed++; } }); return y; }).filter(function(x){ return typeof x!=="string"||plain(x).length>0; }); }); }
function all(){ M.chapters.forEach(dedupe); M.dedupeStats={removed:removed}; }
all(); [1500,4000,8000].forEach(function(t){ setTimeout(all,t); });
M.onNavigate(function(v,arg){ if(v==="read"&&typeof arg==="string"){ var c=M.chapter&&M.chapter(arg); if(c) dedupe(c); } });
/* Symbole im Menü */
var MI={"Abdeckung je Abschluss":"compass","Abdeckungsmatrix":"list","Sprachen & Wortschatz":"book","Ich brauche Hilfe":"lifebuoy","Zuletzt falsch":"retry","Daten":"steps","Fortschritt":"steps","Lernplan":"calendar","Quellen":"book","Einstellungen":"spark","Abschluss wechseln":"shuffle"};
function menuIcons(){ var pop=document.getElementById("menupop"); if(!pop||!M.icon) return; [].forEach.call(pop.querySelectorAll("button,a"),function(b){ if(b.__ic||b.querySelector("svg")) return; var t=b.textContent.trim(); var k=Object.keys(MI).filter(function(x){return t.indexOf(x)===0;})[0]; var name=k? MI[k] : (/^Wortschatz/.test(t)? "book" : (/^Datenschutz|^Impressum|^Nutzung|^Barriere/.test(t)? "book" : "list")); var tmp=document.createElement("span"); tmp.innerHTML=M.icon(name); b.insertBefore(tmp.firstChild,b.firstChild); b.__ic=true; }); }
new MutationObserver(menuIcons).observe(document.body,{childList:true,subtree:true}); menuIcons();
})();

