(function(){"use strict";var M=window.MNEMIKA;if(!M)return;
/* Iteration 16a: Englisch-Navigation auf Deutsch (Inhalte der Lektionen bleiben englisch). */
var UNIT={"Language Skills":"Sprachkompetenz","Written Exam":"Schriftliche Prüfung","Oral Exam":"Mündliche Prüfung","Exam Strategy":"Prüfungsstrategie"};
var TITLE={"en-reading":"Leseverstehen und Textbelege","en-analysis":"Textanalyse auf Englisch","en-writing":"Freier Ausdruck, 200 bis 300 Wörter","en-speaking":"Diskussion, Sprechfluss und Interaktion","en-literature":"Drei literarische Werke und vergleichende Vorbereitung","en-exam-strategy":"Strategie für die dreistündige schriftliche Prüfung"};
function titles(){ (M.chapters||[]).forEach(function(c){ if(TITLE[c.id]) c.title=TITLE[c.id]; if(UNIT[c.unit]) c.unit=UNIT[c.unit]; }); }
titles(); [1500,4000,8000].forEach(function(t){ setTimeout(titles,t); });
/* Iteration 16b: Prüfung planen – Fach, Themen und Datum wählen, dann gezielt üben. */
var KEY="mnemika-exam-plan-v1";
function loadPlan(){ try{ return JSON.parse(localStorage.getItem(KEY)||"null"); }catch(e){ return null; } }
function savePlan(p){ try{ localStorage.setItem(KEY,JSON.stringify(p)); }catch(e){} }
function daysTo(s){ if(!s) return null; var t=new Date(s+"T12:00:00"), n=new Date(); n.setHours(12,0,0,0); var x=Math.round((t-n)/864e5); return isNaN(x)?null:x; }
function openCount(cid){ try{ var r=M.quickPool({count:9999,chapter:cid}); return r.list.length; }catch(e){ return 0; } }
function icon(n){ return M.icon? M.icon(n) : ""; }
M.examTopics=function(sub){
 var v=document.getElementById("v-quick"); if(!v) return;
 var chs=(M.activeChapters? M.activeChapters() : M.chapters).filter(function(c){return c.subject===sub;});
 var plan=loadPlan(); var pre=(plan&&plan.subject===sub&&plan.chapters&&plan.chapters.length)? plan.chapters : chs.map(function(c){return c.id;});
 var old=v.querySelector(".qp-topics"); if(old) old.remove();
 var box=document.createElement("div"); box.className="qp-topics";
 var label=(M.SUBJECTS&&M.SUBJECTS[sub]&&M.SUBJECTS[sub].label)||sub;
 box.innerHTML='<h3>'+icon("target")+'Welche Themen kommen an der Prüfung? · '+label+'</h3><p class="qs-sub" style="margin:0">Wähle die Kapitel, die geprüft werden. Geübt wird nur daraus.</p>'
  +'<div class="qp-tl">'+chs.map(function(c){ var n=openCount(c.id); return '<label><input type="checkbox" value="'+c.id+'"'+(pre.indexOf(c.id)>=0?' checked':'')+'><span>'+String(c.title).replace(/</g,"&lt;")+'</span><small>'+n+' Aufgaben</small></label>'; }).join("")+'</div>'
  +'<p class="qp-sum"></p><div class="qp-acts"><button data-qp="go">'+icon("spark")+'Jetzt üben</button><button data-qp="all">'+icon("list")+'Alle</button><button data-qp="none">'+icon("retry")+'Keine</button><button data-qp="back">'+icon("shuffle")+'Anderes Fach</button></div>';
 var anchor=v.querySelector(".qp-plan")||v.querySelector(".qp-when")||v.firstElementChild; (anchor&&anchor.parentNode? anchor.parentNode : v).insertBefore(box, anchor? anchor.nextSibling : null);
 function sel(){ return [].filter.call(box.querySelectorAll("input"),function(i){return i.checked;}).map(function(i){return i.value;}); }
 function date(){ return (M.examDateFor&&M.examDateFor(sub))||(M.targetDate&&M.targetDate())||null; }
 function sum(){ var s=sel(), open=0; [].forEach.call(box.querySelectorAll("input"),function(i){ if(i.checked){ var sm=i.parentNode.querySelector("small"); open+=parseInt(sm.textContent,10)||0; } });
  var d=date(), n=daysTo(d), per=(n&&n>0)? Math.max(1,Math.ceil(open/n)) : null;
  box.querySelector(".qp-sum").textContent=s.length+(s.length===1?" Kapitel":" Kapitel")+" · "+open+" Aufgaben"+(per? " · etwa "+per+" pro Tag bis "+d.split("-").reverse().join(".") : "");
  box.querySelector('[data-qp="go"]').disabled=!s.length; savePlan({subject:sub,chapters:s,date:d}); return {sel:s,per:per}; }
 box.addEventListener("change",sum); sum();
 box.querySelector('[data-qp="all"]').onclick=function(){ [].forEach.call(box.querySelectorAll("input"),function(i){i.checked=true;}); sum(); };
 box.querySelector('[data-qp="none"]').onclick=function(){ [].forEach.call(box.querySelectorAll("input"),function(i){i.checked=false;}); sum(); };
 box.querySelector('[data-qp="back"]').onclick=function(){ box.remove(); };
 box.querySelector('[data-qp="go"]').onclick=function(){ var r=sum(); if(!r.sel.length) return; var n=Math.min(20,Math.max(5,r.per||10));
  var orig=M.quickPool; M.quickPool=function(o){ var all=orig(Object.assign({},o,{count:9999})); var list=all.list.filter(function(e){return r.sel.indexOf(e.c.id)>=0;}).slice(0,(o&&o.count)||n); return {list:list,counts:all.counts,total:list.length}; };
  try{ M.quickStart({count:n}); } finally { M.quickPool=orig; } };
 box.scrollIntoView&&box.scrollIntoView({block:"nearest"});
};
var base=M.showExamPrep;
M.showExamPrep=function(){ base.apply(this,arguments); var v=document.getElementById("v-quick"); if(!v) return;
 v.querySelectorAll("[data-sub]").forEach(function(b){ var sub=b.dataset.sub; b.onclick=null; b.addEventListener("click",function(e){ e.preventDefault(); e.stopImmediatePropagation(); M.examTopics(sub); },true); }); };
})();

