(function(){"use strict";var M=window.MNEMIKA;if(!M)return;
function icon(n){ return M.icon? M.icon(n) : ""; }
function esc(s){ return String(s==null?"":s).replace(/[&<>"]/g,function(c){return {"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;"}[c];}); }
/* Iteration 17a: gespeicherter Prüfungsplan als Hinweis oben in der Schnellstart-Karte */
function plan(){ try{ return JSON.parse(localStorage.getItem("mnemika-exam-plan-v1")||"null"); }catch(e){ return null; } }
function daysTo(s){ if(!s) return null; var t=new Date(s+"T12:00:00"), n=new Date(); n.setHours(12,0,0,0); var x=Math.round((t-n)/864e5); return isNaN(x)?null:x; }
M.examPractice=function(p,n){ if(!p||!p.chapters||!p.chapters.length) return false; var orig=M.quickPool; M.quickPool=function(o){ var all=orig(Object.assign({},o,{count:9999})); var list=all.list.filter(function(e){return p.chapters.indexOf(e.c.id)>=0;}).slice(0,(o&&o.count)||n||10); return {list:list,counts:all.counts,total:list.length}; }; try{ M.quickStart({count:n||10}); } finally { M.quickPool=orig; } return true; };
function banner(){ var card=document.querySelector("#v-home .qs-card"); if(!card) return; var p=plan(); var old=card.querySelector(".qp-banner");
 if(!p||!p.chapters||!p.chapters.length){ if(old) old.remove(); return; }
 var d=daysTo(p.date); if(d!=null&&d<0){ if(old) old.remove(); return; }
 var open=0; try{ p.chapters.forEach(function(c){ open+=M.quickPool({count:9999,chapter:c}).list.length; }); }catch(e){}
 var per=(d&&d>0)? Math.max(1,Math.ceil(open/d)) : Math.min(10,open);
 var label=(M.SUBJECTS&&M.SUBJECTS[p.subject]&&M.SUBJECTS[p.subject].label)||p.subject;
 var key=[p.subject,p.chapters.join(","),p.date,open].join("|"); if(old&&old.__k===key) return;
 var b=old||document.createElement("div"); b.className="qp-banner"; b.__k=key;
 b.innerHTML=icon("calendar")+'<span><b>Deine Prüfung: '+esc(label)+'</b> · '+(d!=null? "noch "+d+(d===1?" Tag":" Tage")+" ("+p.date.split("-").reverse().join(".")+")" : "ohne Datum")+' · '+p.chapters.length+(p.chapters.length===1?" Thema":" Themen")+' · heute etwa '+per+' Aufgaben</span>'
  +'<button data-pb="go">'+icon("spark")+'Jetzt üben</button><button data-pb="edit">'+icon("pencil")+'Plan ändern</button>';
 if(!old) card.insertBefore(b, card.firstChild);
 b.querySelector('[data-pb="go"]').onclick=function(){ M.examPractice(p, Math.min(20,Math.max(5,per))); };
 b.querySelector('[data-pb="edit"]').onclick=function(){ M.showExamPrep(); setTimeout(function(){ M.examTopics&&M.examTopics(p.subject); },60); }; }
M.examBanner=banner;
/* Iteration 17b: App installieren – nur wo es wirklich geht */
var deferred=null, KEYI="mnemika-install-dismissed";
function standalone(){ return (window.matchMedia&&matchMedia("(display-mode: standalone)").matches)||navigator.standalone===true; }
function ios(){ return /iphone|ipad|ipod/i.test(navigator.userAgent)&&!window.MSStream; }
window.addEventListener("beforeinstallprompt",function(e){ e.preventDefault(); deferred=e; install(); });
window.addEventListener("appinstalled",function(){ deferred=null; var x=document.querySelector(".mn-install"); if(x) x.remove(); });
function install(){ var card=document.querySelector("#v-home .qs-card"); if(!card||standalone()) return; try{ if(localStorage.getItem(KEYI)) return; }catch(e){}
 if(!deferred&&!ios()) return; if(card.querySelector(".mn-install")) return;
 var b=document.createElement("div"); b.className="mn-install";
 b.innerHTML=icon("spark")+'<span>'+(deferred? '<b>Stoffknacker als App installieren:</b> startet schneller und funktioniert offline.' : '<b>Als App speichern:</b> tippe auf «Teilen» und dann auf «Zum Home-Bildschirm».')+'</span>'
  +(deferred? '<button data-in="yes">Installieren</button>' : '')+'<button data-in="no">Später</button>';
 card.appendChild(b);
 var y=b.querySelector('[data-in="yes"]'); if(y) y.onclick=function(){ if(!deferred) return; deferred.prompt(); (deferred.userChoice||Promise.resolve()).then(function(){ deferred=null; b.remove(); }); };
 b.querySelector('[data-in="no"]').onclick=function(){ try{ localStorage.setItem(KEYI,"1"); }catch(e){} b.remove(); }; }
M.installBanner=install;
/* Iteration 17c: Gleich loslegen – ohne Einrichtung direkt in fünf Aufgaben (Passerelle, Standardkonfiguration) */
function now(){ var hero=document.querySelector(".wx-hero"); if(!hero||hero.querySelector(".wx-now")) return; var host=hero.querySelector(".wx-facts"); if(!host) return;
 var btn=document.createElement("button"); btn.type="button"; btn.className="btn go wx-now"; btn.innerHTML=icon("spark")+"Gleich loslegen: 5 Aufgaben ohne Einrichtung";
 host.parentNode.insertBefore(btn, host.nextSibling);
 btn.onclick=function(){ var pb=document.querySelector('[data-prog="passerelle-2023"]'); if(pb) pb.click(); var k=0; (function wait(){ var c=document.getElementById("supcta"); if(c&&!c.disabled){ c.click(); setTimeout(function(){ M.quickStart({count:5}); },300); return; } if(k++<20) setTimeout(wait,150); })(); }; }
function tick(){ banner(); install(); now(); }
M.onDomChange(function(){ clearTimeout(tick.t); tick.t=setTimeout(tick,120); }); tick();
})();

