(function(){"use strict";var M=window.MNEMIKA;if(!M||!M.chapters)return;
/* Iteration 18: Rechtschreibung. Drei Erzeuger hatten Begriffe kleingeschrieben und teils englische
   Arbeitstitel eingesetzt: «Dieses Kapitel konzentriert sich auf …», «Du erarbeitest … und wendest …»,
   Schritte der Anwendungsbeispiele («Kläre …», «Wende … an», «Beziehe … ein»). Die vollständigen
   Begriffe bleiben; jedes Wort wird nach deutscher Regel geschrieben: Substantiv gross, sonst klein.
   Substantiv = in den Texten der App mitten im Satz grossgeschrieben und kaum je klein. */
var EN={"source darstellungsintegrität":"Quellen und Darstellungsintegrität","feasibility":"Machbarkeit","interdisciplinary":"interdisziplinärer","orientation theme":"Orientierungsthema","narrative":"Erzählstruktur","pseudocode":"Pseudocode","methode choice":"Methodenwahl","source":"Quellen","programme selection":"Programmwahl","performance":"Vortrag","task analyse":"Aufgabenanalyse","production plan":"Produktionsplan","evaluation":"Evaluation","description":"Beschreibung","styles":"Stile","context":"Kontext","deliverable":"Ergebnis","energy":"Energie","graphs":"Graphen","strategy":"Strategie","multi-step cases":"mehrstufige Fälle","control checks":"Kontrollen","survey":"Umfrage","observation":"Beobachtung","combine two oder more disciplines":"Verbindung von mindestens zwei Fächern","work-world link":"Bezug zur Arbeitswelt","decomposition":"Zerlegung","gewählt werke":"gewählte Werke","bip":"BIP"};
var cap={}, low={}, built=false;
function stats(){ if(built) return; built=true;
 function add(t){ String(t).replace(/<[^>]+>/g," ").split(/(?<=[.!?:;])\s+/).forEach(function(sen){ var ws=sen.split(/\s+/); for(var i=1;i<ws.length;i++){ var w=ws[i].replace(/^[^A-Za-zÄÖÜäöüß]+|[^A-Za-zÄÖÜäöüß-]+$/g,""); if(w.length<3||/[«"(]/.test(ws[i-1].slice(-1))) continue; var k=w.toLowerCase(); if(/^[A-ZÄÖÜ]/.test(w)) cap[k]=(cap[k]||0)+1; else low[k]=(low[k]||0)+1; } }); }
 function walk(o,d){ if(o==null||d>5) return; if(typeof o==="string"){ if(o.length>12&&o.indexOf("konzentriert sich auf")<0&&o.indexOf("Du erarbeitest")<0) add(o); return; } if(Array.isArray(o)){ o.forEach(function(x){walk(x,d+1);}); return; } if(typeof o==="object") Object.keys(o).forEach(function(k){ if(k!=="examples") walk(o[k],d+1); }); }
 M.chapters.forEach(function(c){ walk(c,0); }); }
function isNoun(w){ var k=w.toLowerCase(); if(/(ung|heit|keit|schaft|tion|ität|ismus|nis|tum)$/.test(k)&&k.length>5) return true; return (cap[k]||0)>=2 && (low[k]||0)*4<=(cap[k]||0); }
function fixWord(w){ if(!/^[A-Za-zÄÖÜäöüß]/.test(w)) return w; if(/^[A-ZÄÖÜ]{2,}$/.test(w)) return w; var parts=w.split("-"); return parts.map(function(p,i){ if(!p) return p; var k=p.toLowerCase(); if(isNoun(p)||(i>0&&parts[0]==="")) return p.charAt(0).toUpperCase()+p.slice(1); if((low[k]||0)>=2&&(cap[k]||0)<=(low[k]||0)) return p.charAt(0).toLowerCase()+p.slice(1); return p; }).join("-"); } /* nur ändern, was sicher ist */
function fixPhrase(ph){ var t=String(ph).trim(); var k=t.toLowerCase(); if(EN[k]) return EN[k]; Object.keys(EN).forEach(function(e){ t=t.replace(new RegExp("\\b"+e.replace(/[-]/g,"\\-")+"\\b","gi"),EN[e]); }); var ws=t.split(/\s+/); return ws.map(function(w,i){ if(/^(und|oder|der|die|das|des|dem|den|von|mit|im|in|zur|zum|für|auf|aus|bei|ein|eine|einer|eines)$/i.test(w)) return w.toLowerCase(); var nx=ws[i+1];
  if(nx&&/^[a-zäöü]+(e|en|er|es)$/i.test(w)&&!/(ung|heit|keit|schaft|tion|ität|ismus|nis)$/i.test(w)&&isNoun(nx.replace(/[^A-Za-zÄÖÜäöüß]/g,""))) return w.toLowerCase();
  return fixWord(w); }).join(" "); }
function fixList(list){ return list.split(/,\s*/).map(fixPhrase).join(", "); }
var fixed=0, MEMO=new Map(); /* R62: gleiche Eingabe ergibt gleiche Ausgabe; Zaehler wie bisher */
function fixStr(s){ if(typeof s!=="string") return s; var mm=MEMO.get(s); if(mm!==undefined){ if(mm!==s) fixed++; return mm; } var y=fixStrRoh(s); MEMO.set(s,y); return y; }
function fixStrRoh(s){ var y=s
 .replace(/(Dieses Kapitel konzentriert sich auf )([^.]+)\./,function(m,a,l){ return a+fixList(l)+"."; })
 .replace(/(Du erarbeitest )(.+?)( und wendest sie)/,function(m,a,l,z){ return a+fixList(l)+z; })
 .replace(/^(.+?) wird mit (.+?) verbunden\.$/,function(m,a,b){ var parts=[a].concat(b.split(/\s+und\s+/)).map(fixPhrase); var last=parts.pop(); return "Zusammenhang: "+parts.join(", ")+" und "+last+"."; })
 .replace(/^(.+?) fachlich erklären und anwenden$/,function(m,a){ return fixPhrase(a)+" fachlich erklären und anwenden"; })
 .replace(/«([^»]{3,40})»/g,function(m,q){ return EN[q.toLowerCase()]? "«"+EN[q.toLowerCase()]+"»" : m; })
 .replace(/, ([a-zäöü][a-zäöüß]+)(?=, | und )/g,function(m,w){ var n=cap[w]||0; return n>=20&&n>=20*(low[w]||0)? ", "+w.charAt(0).toUpperCase()+w.slice(1) : m; }); /* eindeutige Substantive in Aufzählungen */
 if(y!==s) fixed++; return y; }
function walkFix(o,d){ if(!o||d>4) return; Object.keys(o).forEach(function(k){ var v=o[k]; if(typeof v==="string"){ var y=fixStr(v); if(y!==v) o[k]=y; } else if(Array.isArray(v)){ v.forEach(function(x,i){ if(typeof x==="string"){ var y=fixStr(x); if(y!==x) v[i]=y; } else if(x&&typeof x==="object") walkFix(x,d+1); }); } else if(v&&typeof v==="object") walkFix(v,d+1); }); }
function fixChapter(c){ stats(); if(c.__spell2) return; c.__spell2=true; if(/^(en|fr|it|es|la|rm)-/.test(c.id)){ return; } walkFix(c,0);
 (c.examples||[]).forEach(function(ex){ if(!ex||!Array.isArray(ex.steps)) return; ex.steps=ex.steps.map(function(s){ if(typeof s!=="string") return s; var m;
  if((m=s.match(/^(?:Kläre (.+)\.|Klären: (.+))$/))){ fixed++; return "Klären: "+fixList(m[1]||m[2]); }
  if((m=s.match(/^(?:Wende (.+) an\.|Anwenden: (.+))$/))){ fixed++; return "Anwenden: "+fixList(m[1]||m[2]); }
  if((m=s.match(/^(?:Beziehe (.+) ein\.|Einbeziehen: (.+))$/))){ fixed++; return "Einbeziehen: "+fixList(m[1]||m[2]); }
  if(s==="Kontrolliere Ergebnis und Begründung."){ fixed++; return "Kontrollieren: Ergebnis und Begründung"; }
  return s; }); }); }
function all(){ M.chapters.forEach(function(c){ fixChapter(c); }); M.spellingFix={fixed:fixed}; }
M.fixChapterText=fixChapter; M.germanNoun=isNoun;
all(); [1500,4000,8000].forEach(function(t){ setTimeout(function(){ M.chapters.forEach(function(c){ c.__spell2=false; }); all(); },t); });
M.onNavigate(function(v,arg){ if(v==="read"&&typeof arg==="string"){ var c=M.chapter&&M.chapter(arg); if(c){ c.__spell2=false; fixChapter(c); } } });
})();

