(function(){"use strict";var M=window.MNEMIKA;if(!M)return;
/* Iteration 26: Hilfe zur Frage passend statt beliebig.
   «Beispiel» und «Schritt für Schritt» nahmen immer das erste Beispiel des Kapitels, unabhängig von der Frage.
   Jetzt wird das Beispiel gewählt, das inhaltlich am besten zur Frage passt; gibt es keines, wird der zur Frage
   gehörende Lektionsabschnitt gezeigt. «Einfacher erklärt» beginnt bei der Frage selbst; Kapitelhinweise werden
   als solche bezeichnet. */
var STOP=" der die das und oder eine einen einem eines dem den ist sind wird werden nicht auch für mit von bei aus dass sich auf als was wie wenn man kann sein ihre seine mehr sehr etwa beim zum zur dabei damit dann noch schon nur über unter zwischen ".split(" ");
function toks(s){ return String(s==null?"":s).toLowerCase().replace(/[^0-9a-zäöüß]+/g," ").split(" ").filter(function(w){ return w.length>=4&&STOP.indexOf(w)<0; }); }
function score(a,b){ var A=toks(a), B=toks(b), n=0, seen={}; A.forEach(function(t){ if(!seen[t]&&B.indexOf(t)>=0){ seen[t]=1; n++; } }); return n; }
function qText(q){ return [q&&q.prompt,q&&q.q,q&&q.explanation,q&&q.hint,(q&&q.options||[]).join(" "),(q&&q.answer)].filter(Boolean).join(" "); }
function exText(e){ return [e&&e.task,e&&e.title,(e&&e.steps||[]).join(" "),e&&e.text].filter(Boolean).join(" "); }
M.bestExampleFor=function(c,q){ var list=(c&&c.examples)||[]; if(!list.length) return null; var t=qText(q), best=null, bs=-1;
 list.forEach(function(e){ var s=score(t,exText(e)); if(s>bs){ bs=s; best=e; } }); return bs>0?best:null; };
M.helpSourceFor=function(c,q){ var e=M.bestExampleFor(c,q); if(e) return {art:"beispiel", ex:e};
 var bl=(M.bestBlockFor&&M.bestBlockFor(c,q))||null;
 if(!bl){ var t=qText(q), bb=null, bs=-1; ((c&&c.blocks)||[]).forEach(function(b){ var s=score(t,[b.label,(b.body||[]).join(" ")].join(" ")); if(s>bs){ bs=s; bb=b; } }); bl=bs>0?bb:((c&&c.blocks)||[])[0]||null; }
 return {art:"abschnitt", block:bl}; };
})();

